# Base StudentRecord class (adding get_grade)
class StudentRecord:
    def __init__(self, name, test_score, phone_duration, attention_label):
        self.name = name
        self.test_score = test_score
        self.phone_duration = phone_duration
        self.attention_label = attention_label

    def is_attentive(self):
        return self.attention_label == 'Attentive'

    def is_distracted(self):
        return self.phone_duration > 60

    def get_grade(self):
        if self.test_score >= 90: return 'A'
        elif self.test_score >= 80: return 'B'
        elif self.test_score >= 70: return 'C'
        elif self.test_score >= 60: return 'D'
        else: return 'F'

    def __str__(self):
        return f"{self.name}: Score={self.test_score}, Phone={self.phone_duration}s, Label={self.attention_label}"

    def __repr__(self):
        return f"StudentRecord('{self.name}', {self.test_score}, {self.phone_duration}, '{self.attention_label}')"

# UndergradRecord Class
class UndergradRecord(StudentRecord):
    def __init__(self, name, test_score, phone_duration, attention_label, major):
        super().__init__(name, test_score, phone_duration, attention_label)
        self.major = major

    def display_major(self):
        print(f"{self.name}'s major: {self.major}")

    # Optional: Override __str__ to include major
    def __str__(self):
        base_str = super().__str__()
        return f"{base_str}, Major: {self.major}"

# GradStudentRecord Class
class GradStudentRecord(StudentRecord):
    def __init__(self, name, test_score, phone_duration, attention_label, thesis_topic):
        super().__init__(name, test_score, phone_duration, attention_label)
        self.thesis_topic = thesis_topic

    def __str__(self):
        base_str = super().__str__()
        return f"{base_str}, Thesis: {self.thesis_topic}"

    def get_grade(self):
        return 'Pass' if self.test_score >= 70 else 'Fail'

# Create a list of mixed student types
all_students = [
    StudentRecord("Generic Sam", 65, 70, "Distracted"),
    UndergradRecord("Morgan", 88, 45, "Attentive", "Computer Science"),
    GradStudentRecord("Riley", 75, 25, "Attentive", "AI Ethics"),
    UndergradRecord("Jordan", 91, 15, "Attentive", "Biology"),
    GradStudentRecord("Alex", 68, 55, "Distracted", "Quantum Physics")
]

print("Processing all students:\n")

# Loop through the list and demonstrate polymorphism
for student in all_students:
    print(student) # Calls the appropriate __str__ based on object type
    print(f"Calculated Grade: {student.get_grade()}") # Calls the appropriate get_grade
    print() # Blank line
